{
  "justification": "Vote-deciding concerns are dominated by public services (health, education, elderly care), and the electorate is left-leaning with strong support for higher taxes and spending, pushing Care and Equality to the fore. Identity, order, and purity-related items register only modest salience, so Loyalty, Authority, and Sanctity are comparatively weak.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "High salience of health (33.6%), education (25.6%), pensions/elderly care (4.3%), welfare (1.0%), housing (0.5%), environment (1.0%).",
      "weight": 0.45
    },
    {
      "foundation": "equality",
      "basis": "Preference to increase taxes and services (71.3%) and left-leaning mean (2.39/5) indicate support for equal treatment/outcomes.",
      "weight": 0.23
    },
    {
      "foundation": "proportionality",
      "basis": "Minority favoring tax/service reductions (28.7%) plus salience of macro-economy (7.9%), tax (3.2%), and inflation/wages (1.2%).",
      "weight": 0.12
    },
    {
      "foundation": "authority",
      "basis": "Salience of law and order/crime/policing/sentencing/prisons (3.6%) and some family values (0.2%).",
      "weight": 0.10
    },
    {
      "foundation": "loyalty",
      "basis": "Very low salience of defense (0.2%), immigration/refugees (0.2%), and other national-identity items (EU not measured).",
      "weight": 0.06
    },
    {
      "foundation": "sanctity",
      "basis": "Small nods to purity/naturalness via family values (0.2%) and environment (1.0%).",
      "weight": 0.04
    }
  ]
}
